{
  "name": "opencode-superwhisper-v2",
  "version": "2.0.0",
  "description": "OpenCode V2 plugin for Superwhisper voice notifications and hands-free replies",
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": "./index.js"
  },
  "files": [
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "superwhisper",
    "voice",
    "notifications",
    "ai",
    "coding-agent"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/aryanbatras/opencode-superwhisper-v2"
  },
  "homepage": "https://github.com/aryanbatras/opencode-superwhisper-v2",
  "bugs": {
    "url": "https://github.com/aryanbatras/opencode-superwhisper-v2/issues"
  },
  "engines": {
    "node": ">=20"
  }
}

import { execFile } from "node:child_process"
import { appendFileSync, existsSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs"
import { homedir } from "node:os"
import { join } from "node:path"
import { randomUUID } from "node:crypto"
import { promisify } from "node:util"

const run = promisify(execFile)

const LOG_PREFIX = "[superwhisper]"
const MESSAGE_DIR = process.env.SUPERWHISPER_DIR || "/tmp/superwhisper-agent"
const INBOX_DIR = join(homedir(), "Library/Application Support/superwhisper/agent/inbox")
const POLL_INTERVAL_MS = Number(process.env.SUPERWHISPER_POLL_INTERVAL_MS) || 1000
const POLL_TIMEOUT_MS = Number(process.env.SUPERWHISPER_POLL_TIMEOUT_MS) || 30 * 60 * 1000
const CANCELLED = "$$CANCELLED$$"
const LOG_FILE = `${MESSAGE_DIR}/debug.log`
const DEBUG = !!process.env.SUPERWHISPER_DEBUG

export function extractFullText(message) {
  if (!message?.content) return ""
  return message.content
    .filter((part) => part.type === "text")
    .map((part) => part.text || "")
    .join("\n")
    .trim()
}

export function isEndTurn(message) {
  if (!message) return false
  const finish = message.finish
  return !finish || finish === "stop" || finish === "length" || finish === "unknown"
}

export function extractSummary(text) {
  if (!text) return ""
  const maxLength = 200
  if (text.length <= maxLength) return text
  const sentenceEnd = text.substring(0, maxLength).lastIndexOf(". ")
  if (sentenceEnd > 100) return text.substring(0, sentenceEnd + 1)
  const wordEnd = text.substring(0, maxLength).lastIndexOf(" ")
  if (wordEnd > 150) return text.substring(0, wordEnd) + "..."
  return text.substring(0, maxLength) + "..."
}

export function normalizePermissionReply(raw) {
  const value = raw.trim().toLowerCase()
  if (value === "bypass" || value.includes("bypass")) return "bypass"
  if (value === "always" || value.includes("always")) return "always"
  if (value === "reject" || value === "deny" || value === "no" || value.includes("deny") || value.includes("reject")) {
    return "reject"
  }
  return "once"
}

export function pollForResponse(path, timeoutMs = POLL_TIMEOUT_MS, intervalMs = POLL_INTERVAL_MS, isCancelled) {
  const deadline = Date.now() + timeoutMs
  return new Promise((resolve) => {
    const tick = () => {
      if (isCancelled?.()) return resolve(null)
      if (Date.now() >= deadline) return resolve(null)
      try {
        if (existsSync(path)) {
          const text = readFileSync(path, "utf8")
          if (text && text.trim().length > 0) return resolve(text)
        }
      } catch {}
      setTimeout(tick, intervalMs)
    }
    tick()
  })
}

function log(level, message) {
  if (!DEBUG) return
  try {
    appendFileSync(LOG_FILE, `[${new Date().toISOString()}] [${level}] ${LOG_PREFIX} ${message}\n`)
  } catch {}
}

function writeInboxPayload(payload) {
  try {
    mkdirSync(INBOX_DIR, { recursive: true })
  } catch {
    return false
  }
  const id = randomUUID()
  const tmpPath = join(INBOX_DIR, `${id}.json.tmp`)
  const finalPath = join(INBOX_DIR, `${id}.json`)
  try {
    writeFileSync(tmpPath, JSON.stringify(payload))
    renameSync(tmpPath, finalPath)
    return true
  } catch {
    try {
      unlinkSync(tmpPath)
    } catch {}
    return false
  }
}

async function isSuperwhisperRunning() {
  try {
    await run("pgrep", ["-x", "superwhisper"])
    return true
  } catch {
    return false
  }
}

async function detectScheme() {
  if (process.env.SUPERWHISPER_SCHEME) return process.env.SUPERWHISPER_SCHEME
  try {
    await run("pgrep", ["-f", "DerivedData.*superwhisper.app"])
    return "superwhisper-debug"
  } catch {
    return "superwhisper"
  }
}

async function fireAgentWake(scheme) {
  try {
    await run("open", [`${scheme}://agent-wake`])
  } catch {}
}

async function deliverAgentPayload(payload, scheme) {
  const wrote = writeInboxPayload(payload)
  if (!(await isSuperwhisperRunning())) await fireAgentWake(scheme)
  return wrote
}

async function getGitBranch(directory) {
  try {
    const { stdout } = await run("git", ["-C", directory, "rev-parse", "--abbrev-ref", "HEAD"])
    return stdout.trim()
  } catch {
    return undefined
  }
}

function eventData(event) {
  return event?.data ?? event?.properties ?? {}
}

export default {
  id: "superwhisper",
  async setup(ctx) {
    const directory = ctx.location?.directory || process.cwd()
    const projectName = directory.split("/").pop() || ctx.location?.project?.id || ""
    const scheme = await detectScheme()
    mkdirSync(MESSAGE_DIR, { recursive: true })

    const activePolls = new Map()
    const permissionActiveForSession = new Set()
    const disabledSessions = new Set()
    const repliedPermissionIds = new Set()
    const activePermissionResponseFiles = new Map()
    const injectedSessions = new Set()
    const sessionTitles = new Map()
    const subagentSessions = new Set()
    const lastText = new Map()
    const textParts = new Map()
    const controller = new AbortController()
    let stopped = false

    const isSessionDisabled = (sessionID) =>
      disabledSessions.has(sessionID) || existsSync(`${MESSAGE_DIR}/disabled-${sessionID}`)

    const disableSession = (sessionID) => {
      disabledSessions.add(sessionID)
      try {
        writeFileSync(`${MESSAGE_DIR}/disabled-${sessionID}`, "")
      } catch (error) {
        log("error", `Failed to write disabled flag for session=${sessionID}: ${error}`)
      }
    }

    const enableSession = (sessionID) => {
      disabledSessions.delete(sessionID)
      try {
        const path = `${MESSAGE_DIR}/disabled-${sessionID}`
        if (existsSync(path)) unlinkSync(path)
      } catch (error) {
        log("error", `Failed to remove disabled flag for session=${sessionID}: ${error}`)
      }
    }

    const getSessionContext = (sessionID) => ctx.session.context({ sessionID })

    const getLastAssistantMessage = (messages) =>
      [...messages].reverse().find((message) => message.type === "assistant")

    const cancelPoll = (key, source) => {
      const poll = activePolls.get(key)
      if (!poll) return false
      poll.cancel()
      activePolls.delete(key)
      log("debug", `Poll cancelled for key=${key} (${source})`)
      return true
    }

    const sendDismiss = (sessionID, source) => {
      log("debug", `Sending dismiss (${source}) for session=${sessionID}`)
      deliverAgentPayload({ kind: "dismiss", sessionId: sessionID }, scheme).catch((error) => {
        log("error", `Failed to send dismiss for session=${sessionID}: ${error}`)
      })
    }

    const sendNotification = async ({ sessionID, status, summary, messageContent, pollKey = sessionID }) => {
      cancelPoll(pollKey, "replaced")

      const messageFile = `${MESSAGE_DIR}/${pollKey}-message.txt`
      const responseFile = `${MESSAGE_DIR}/${pollKey}-response.txt`
      try {
        writeFileSync(messageFile, messageContent)
      } catch (error) {
        log("error", `Failed to write message file ${messageFile}: ${error}`)
        return null
      }
      try {
        if (existsSync(responseFile)) unlinkSync(responseFile)
      } catch {}

      const branch = await getGitBranch(directory)
      try {
        await deliverAgentPayload(
          {
            kind: "update",
            agent: "opencode",
            status,
            sessionId: sessionID,
            summary,
            messageFile,
            responseFile,
            cwd: directory,
            project: projectName,
            branch,
            title: sessionTitles.get(sessionID),
            hookPid: process.pid,
          },
          scheme,
        )
      } catch (error) {
        log("error", `Failed to deliver Superwhisper payload: ${error}`)
        return null
      }

      let cancelled = false
      const token = Symbol()
      activePolls.set(pollKey, {
        cancel: () => {
          cancelled = true
        },
        token,
      })
      const response = await pollForResponse(responseFile, POLL_TIMEOUT_MS, POLL_INTERVAL_MS, () => cancelled || stopped)
      const current = activePolls.get(pollKey)
      if (current?.token === token) activePolls.delete(pollKey)
      if (cancelled || stopped) return CANCELLED
      if (response === null) {
        log("info", `Poll timed out for session=${sessionID}`)
        return null
      }
      try {
        unlinkSync(responseFile)
        unlinkSync(messageFile)
      } catch {}
      return response
    }

    const sendResponseToOpenCode = async (sessionID, response) => {
      if (!response) return
      try {
        injectedSessions.add(sessionID)
        await ctx.session.prompt({ sessionID, text: response })
        log("info", `Response sent back to session=${sessionID}`)
      } catch (error) {
        log("error", `Failed to send response to session=${sessionID}: ${error}`)
      }
    }

    const replyToPermission = async (sessionID, requestID, decision) => {
      try {
        await ctx.permission.reply({ sessionID, requestID, decision })
        log("info", `Permission reply sent requestID=${requestID} decision=${decision}`)
      } catch (error) {
        log("error", `Failed to reply to permission requestID=${requestID}: ${error}`)
      }
    }

    const handleSessionBusy = (sessionID, source) => {
      const busy =
        activePolls.has(sessionID) ||
        permissionActiveForSession.has(sessionID)
      if (!busy) return
      if (injectedSessions.has(sessionID)) {
        cancelPoll(sessionID, source)
        injectedSessions.delete(sessionID)
        return
      }
      cancelPoll(sessionID, source)
      permissionActiveForSession.delete(sessionID)
      sendDismiss(sessionID, source)
    }

    const handleCompleted = async (event) => {
      const sessionID = eventData(event).sessionID
      if (!sessionID || isSessionDisabled(sessionID) || subagentSessions.has(sessionID)) return
      if (permissionActiveForSession.has(sessionID)) return

      const messages = await getSessionContext(sessionID)
      const last = messages[messages.length - 1]
      if (last?.type === "idle" && last.outcome && last.outcome !== "succeeded") {
        log("info", `Skipping idle for session=${sessionID} (outcome=${last.outcome})`)
        return
      }
      const lastAssistant = getLastAssistantMessage(messages)
      const storedText = extractFullText(lastAssistant)
      const fullMessage = (storedText && isEndTurn(lastAssistant) ? storedText : undefined) || lastText.get(sessionID)
      if (!fullMessage) {
        log("info", `Skipping idle for session=${sessionID} (no finished text)`)
        return
      }

      const response = await sendNotification({
        sessionID,
        status: "completed",
        summary: extractSummary(fullMessage),
        messageContent: fullMessage,
      })
      if (response === CANCELLED) return
      if (permissionActiveForSession.has(sessionID)) return
      if (response) {
        await sendResponseToOpenCode(sessionID, response)
      } else {
        sendDismiss(sessionID, "completed-timeout")
      }
    }

    const handleError = async (event) => {
      const data = eventData(event)
      const sessionID = data.sessionID || "unknown"
      if (isSessionDisabled(sessionID) || subagentSessions.has(sessionID)) return
      const errorMessage =
        typeof data.error === "string" ? data.error : data.error?.message || JSON.stringify(data.error ?? "An error occurred")
      const response = await sendNotification({
        sessionID,
        status: "error",
        summary: errorMessage.substring(0, 200),
        messageContent: errorMessage,
      })
      if (response === CANCELLED) return
      if (response) await sendResponseToOpenCode(sessionID, response)
      else sendDismiss(sessionID, "error-timeout")
    }

    const handlePermission = async (event) => {
      const data = eventData(event)
      const sessionID = data.sessionID || "unknown"
      if (isSessionDisabled(sessionID) || subagentSessions.has(sessionID)) return
      const permissionID = data.id
      if (!permissionID) return

      const action = data.action || "unknown"
      const resources = data.resources || []
      const bypassFile = `${MESSAGE_DIR}/${sessionID}-bypass-perms`
      if (existsSync(bypassFile)) {
        log("info", `Bypass active for session=${sessionID}, auto-allowing ${action}`)
        repliedPermissionIds.add(permissionID)
        await replyToPermission(sessionID, permissionID, "once")
        return
      }

      permissionActiveForSession.add(sessionID)
      const responseFile = `${MESSAGE_DIR}/${permissionID}-response.txt`
      activePermissionResponseFiles.set(permissionID, responseFile)
      const summary = `Permission needed: ${action}`
      const response = await sendNotification({
        sessionID,
        status: "permission",
        summary,
        pollKey: permissionID,
        messageContent: JSON.stringify({
          permissionId: permissionID,
          toolName: action,
          summary,
          details: resources.join(", "),
          suggestions: [
            { label: "Allow", behavior: "allow" },
            { label: "Always Allow", behavior: "always" },
            { label: "Bypass permissions for this session", behavior: "bypass-perms" },
            { label: "Deny", behavior: "deny" },
          ],
        }),
      })
      activePermissionResponseFiles.delete(permissionID)
      permissionActiveForSession.delete(sessionID)
      if (response === CANCELLED) return
      if (!response) {
        sendDismiss(sessionID, `permission-timeout(${permissionID})`)
        return
      }

      const normalized = normalizePermissionReply(response)
      if (normalized === "bypass") {
        try {
          writeFileSync(bypassFile, "")
          log("info", `Bypass mode enabled for session=${sessionID}`)
        } catch (error) {
          log("error", `Failed to write bypass file: ${error}`)
        }
      }
      repliedPermissionIds.add(permissionID)
      await replyToPermission(sessionID, permissionID, normalized === "bypass" ? "once" : normalized)
    }

    const handlePermissionReplied = (event) => {
      const data = eventData(event)
      const sessionID = data.sessionID
      const permissionID = data.requestID || data.id
      if (!permissionID) return
      if (repliedPermissionIds.has(permissionID)) {
        repliedPermissionIds.delete(permissionID)
        permissionActiveForSession.delete(sessionID)
        return
      }
      const responseFile = activePermissionResponseFiles.get(permissionID)
      if (responseFile) {
        try {
          writeFileSync(responseFile, data.reply || "once")
        } catch (error) {
          log("warn", `Failed to unblock permission ${permissionID}: ${error}`)
        }
      }
      if (sessionID) {
        permissionActiveForSession.delete(sessionID)
        cancelPoll(permissionID, `permission.replied(${permissionID})`)
        sendDismiss(sessionID, `permission.replied(${permissionID})`)
      }
    }

    const handleSessionCreated = (event) => {
      const data = eventData(event)
      if (!data.sessionID) return
      if (data.parentID) subagentSessions.add(data.sessionID)
      if (typeof data.title === "string" && !data.title.startsWith("New session - ")) {
        sessionTitles.set(data.sessionID, data.title)
      }
    }

    const handleEvent = async (event) => {
      // shortcut: V2 forms (form.created) are not answered; plugin context exposes no form API, upgrade when it does.
      switch (event.type) {
        case "session.idle":
          await handleCompleted(event)
          break
        case "session.execution.failed":
          await handleError(event)
          break
        case "session.status": {
          const data = eventData(event)
          if (data.status?.type === "busy" && data.sessionID) handleSessionBusy(data.sessionID, "session.status(busy)")
          break
        }
        case "session.text.ended": {
          const data = eventData(event)
          if (!data.sessionID || !data.text) break
          const key = `${data.sessionID}|${data.assistantMessageID}`
          const parts = textParts.get(key) || new Map()
          parts.set(data.ordinal ?? 0, data.text)
          textParts.set(key, parts)
          lastText.set(
            data.sessionID,
            [...parts.entries()]
              .sort(([a], [b]) => a - b)
              .map(([, text]) => text)
              .join("\n"),
          )
          break
        }
        case "session.inbox.delivered": {
          const sessionID = eventData(event).sessionID
          if (!sessionID) break
          lastText.delete(sessionID)
          for (const key of textParts.keys()) {
            if (key.startsWith(`${sessionID}|`)) textParts.delete(key)
          }
          break
        }
        case "permission.asked":
          await handlePermission(event)
          break
        case "permission.replied":
          handlePermissionReplied(event)
          break
        case "session.created":
          handleSessionCreated(event)
          break
        case "session.forked": {
          const data = eventData(event)
          if (data.sessionID && data.parentID) subagentSessions.add(data.sessionID)
          break
        }
        case "session.renamed": {
          const data = eventData(event)
          if (data.sessionID && data.title) sessionTitles.set(data.sessionID, data.title)
          break
        }
        case "session.deleted": {
          const sessionID = eventData(event).sessionID
          if (!sessionID) break
          cancelPoll(sessionID, "session.deleted")
          lastText.delete(sessionID)
          sessionTitles.delete(sessionID)
          subagentSessions.delete(sessionID)
          permissionActiveForSession.delete(sessionID)
          disabledSessions.delete(sessionID)
          for (const key of textParts.keys()) {
            if (key.startsWith(`${sessionID}|`)) textParts.delete(key)
          }
          break
        }
      }
    }

    await ctx.tool.transform((editor) => {
      editor.add({
        name: "superwhisper_toggle",
        description:
          "Enable or disable Superwhisper voice notifications for this session. Use action='disable' when the user wants to turn Superwhisper off, and action='enable' when they want to turn it back on.",
        input: {
          type: "object",
          properties: { action: { type: "string", enum: ["enable", "disable"] } },
          required: ["action"],
          additionalProperties: false,
        },
        execute: async ({ action }, context) => {
          const sessionID = context.sessionID
          if (action === "disable") {
            disableSession(sessionID)
            return { content: "Superwhisper voice notifications disabled for this session." }
          }
          enableSession(sessionID)
          return { content: "Superwhisper voice notifications re-enabled for this session." }
        },
      })
    })

    void (async () => {
      try {
        for await (const event of ctx.event.subscribe({
          types: [
            "session.idle",
            "session.execution.failed",
            "session.status",
            "session.text.ended",
            "session.inbox.delivered",
            "session.created",
            "session.forked",
            "session.renamed",
            "session.deleted",
            "permission.asked",
            "permission.replied",
          ],
          signal: controller.signal,
        })) {
          void handleEvent(event).catch((error) => log("error", `Event ${event.type} failed: ${error}`))
        }
      } catch (error) {
        if (!controller.signal.aborted) log("error", `Event subscription failed: ${error}`)
      }
    })()

    log("info", `Loaded for directory=${directory} scheme=${scheme}`)

    return () => {
      stopped = true
      controller.abort()
      for (const poll of activePolls.values()) poll.cancel()
      activePolls.clear()
    }
  },
}
